      es: ["El reino existió aproximadamente entre 1075 y 1220.", "El famoso rinoceronte dorado de Mapungubwe fue descubierto aquí."],
      pt: ["O reino existiu aproximadamente entre 1075 e 1220.", "O famoso rinoceronte dourado de Mapungubwe foi descoberto aqui."],
